INSERT INTO hs_codes (code, description) VALUES
  ('8708.2120', 'Parts and accessories of the motor vehicles of headings 87.01 to 87.05. (i) Front and Rear Bumper and parts thereof (ii) Member/reinforcement for bumpers (iii) Side supports / stay/ bracket for bumpers (2) Front bumper and parts thereof for vehicles of sub – headings 8704.2190, 8704.3130, 8704.3150 and 8704.3190 > Other parts and accessories of bodies (including cabs): > Safety seat belts: > For vehicles of heading 87.02 and sub-headings 8701.2020, 8701.2090, 8701.2040, 8704.2219, 8704.2299 and 8704.2390'),
  ('8708.2190', 'Parts and accessories of the motor vehicles of headings 87.01 to 87.05. (i) Front and Rear Bumper and parts thereof (ii) Member/reinforcement for bumpers (iii) Side supports / stay/ bracket for bumpers (2) Front bumper and parts thereof for vehicles of sub – headings 8704.2190, 8704.3130, 8704.3150 and 8704.3190 > Other parts and accessories of bodies (including cabs): > Safety seat belts: > Other'),
  ('8708.2200', 'Parts and accessories of the motor vehicles of headings 87.01 to 87.05. (i) Front and Rear Bumper and parts thereof (ii) Member/reinforcement for bumpers (iii) Side supports / stay/ bracket for bumpers (2) Front bumper and parts thereof for vehicles of sub – headings 8704.2190, 8704.3130, 8704.3150 and 8704.3190 > Other parts and accessories of bodies (including cabs): > Front windscreens (windshields), rear windows and other windows specified in Subheading Note 1 to this Chapter'),
  ('8708.2911', 'Parts and accessories of the motor vehicles of headings 87.01 to 87.05. (i) Front and Rear Bumper and parts thereof (ii) Member/reinforcement for bumpers (iii) Side supports / stay/ bracket for bumpers (2) Front bumper and parts thereof for vehicles of sub – headings 8704.2190, 8704.3130, 8704.3150 and 8704.3190 > Other parts and accessories of bodies (including cabs): > Other: > For vehicles of heading 87.01: > (A) Following components for vehicles of sub-heading 8701.2020, 8701.2090 and 8701.2040 (1) Battery carrier assembly and parts thereof (2) Cabin tilt stay stopper assembly (3) Cross members for frame (4) Floor mat assembly set (5) Foot steps for cabin entry (6) For 4x2 vehicles: Brackets for shock absorber mounting; Brackets for mounting engine (casting and sheet metal type) ; Brackets for exhaust pipe; Brackets / support for air and vacuum tank ; Brackets for mounting pedal set ; Brackets assembly for leaf spring assembly (casting) ; Brackets for air cleaner (7) Frame assembly (8) Gussets / stiffeners for frame (9) Licence plate assembly and parts thereof (10) Long members for frame (4x2 vehicles only) (11) Mounting support for spare wheel carrier (12) Rear body trim (13) Rear member assembly for cabin mounting (14) Shroud for fan (15) Sun visor (B) Following components for agricultural tractors of sub- headings 8701.9220 and 8701.9320 (1) Battery box assembly and parts thereof (2) Body shield / guard PTO (3) Cowl radiator assembly and parts thereof (4) Fan shroud assembly and parts thereof (5) Fender assemblies and parts thereof (6) Filler neck for lubricating oil (7) Flaps for front hood (8) Foot rest (9) Foot step / foot board assemblies and parts there of (10) Grill assembly / hood cowling assembly and parts thereof (11) Guard / protector for PTO (12) Heat shields (13) Hood assembly and parts thereof (14) Instrument panels (15) Seat support assembly and parts thereof (16)Side channels (17) Side grill (18) Support for front throttle (19) Warning indicator housing'),
